1056	impl WriteHandle {
1057	    /// Check the status on the inode and set it to writing state if it's writable
1058	    fn new(inner: Arc<SuperblockInner>, ino: InodeNo, parent_ino: InodeNo, pid: u32) -> Result<Self, InodeError> {
1059	        let inode = inner.get(ino)?;
1060	        let mut state = inode.get_mut_inode_state()?;
1061	        match state.write_status {
1062	            WriteStatus::LocalUnopened => {
1063	                state.write_status = WriteStatus::LocalOpen;
1064	                Ok(Self {
1065	                    inner,
1066	                    ino,
1067	                    parent_ino,
1068	                    pid,
1069	                })
1070	            }
1071	            WriteStatus::LocalOpen => Err(InodeError::InodeAlreadyWriting(inode.err())),
1072	            WriteStatus::Remote => Err(InodeError::InodeNotWritable(inode.err())),
1073	        }
1074	    }
1075	
1076	    /// The pid of the process which opened this handle.
1077	    pub fn pid(&self) -> u32 {
1078	        self.pid
1079	    }
1080	
1081	    /// Update status of the inode and of containing "local" directories.
1082	    pub fn finish_writing(self) -> Result<(), InodeError> {
1083	        let inode = self.inner.get(self.ino)?;
1084	
1085	        // Collect ancestor inodes that may need updating,
1086	        // from parent to first remote ancestor.
1087	        let ancestors = {
1088	            let mut ancestors = Vec::new();
1089	            let mut ancestor_ino = self.parent_ino;
1090	            let mut visited = HashSet::new();
1091	            loop {
1092	                assert!(visited.insert(ancestor_ino), "cycle detected in inode ancestors");
1093	                let ancestor = self.inner.get(ancestor_ino)?;
1094	                ancestors.push(ancestor.clone());
1095	                if ancestor.ino() == ROOT_INODE_NO || ancestor.get_inode_state()?.write_status == WriteStatus::Remote {
1096	                    break;
1097	                }
1098	                ancestor_ino = ancestor.parent();
1099	            }
1100	            ancestors
1101	        };
1102	
1103	        // Acquire locks on ancestors in descending order to avoid deadlocks.
1104	        let mut ancestors_states = ancestors
1105	            .iter()
1106	            .rev()
1107	            .map(|inode| inode.get_mut_inode_state())
1108	            .collect::<Result<Vec<_>, _>>()?;
1109	
1110	        let mut state = inode.get_mut_inode_state()?;
1111	        match state.write_status {
1112	            WriteStatus::LocalOpen => {
1113	                state.write_status = WriteStatus::Remote;
1114	
1115	                // Invalidate the inode's stats so we refresh them from S3 when next queried
1116	                state.stat.update_validity(Duration::from_secs(0));
1117	
1118	                // Walk up the ancestors from parent to first remote ancestor to transition
1119	                // the inode and all "local" containing directories to "remote".
1120	                let children_inos = std::iter::once(self.ino).chain(ancestors.iter().map(|ancestor| ancestor.ino()));
1121	                for (ancestor_state, child_ino) in ancestors_states.iter_mut().rev().zip(children_inos) {
1122	                    match &mut ancestor_state.kind_data {
1123	                        InodeKindData::File { .. } => unreachable!("we know the ancestor is a directory"),
1124	                        InodeKindData::Directory { writing_children, .. } => {
1125	                            writing_children.remove(&child_ino);
1126	                        }
1127	                    }
1128	                    ancestor_state.write_status = WriteStatus::Remote;
1129	                }
1130	
1131	                Ok(())
1132	            }
1133	            _ => Err(InodeError::InodeNotWritable(inode.err())),
1134	        }
1135	    }
1136	}
