240	    /// Set the attributes for an inode
241	    pub async fn setattr<OC: ObjectClient>(
242	        &self,
243	        _client: &OC,
244	        ino: InodeNo,
245	        atime: Option<OffsetDateTime>,
246	        mtime: Option<OffsetDateTime>,
247	    ) -> Result<LookedUp, InodeError> {
248	        let inode = self.inner.get(ino)?;
249	        logging::record_name(inode.name());
250	        let mut sync = inode.get_mut_inode_state()?;
251	
252	        if sync.write_status == WriteStatus::Remote {
253	            return Err(InodeError::SetAttrNotPermittedOnRemoteInode(inode.err()));
254	        }
255	
256	        let validity = match inode.kind() {
257	            InodeKind::File => self.inner.config.cache_config.file_ttl,
258	            InodeKind::Directory => self.inner.config.cache_config.dir_ttl,
259	        };
260	
261	        // Resetting the InodeStat expiry because the new InodeStat should have new validity
262	        sync.stat.update_validity(validity);
263	
264	        if let Some(t) = atime {
265	            sync.stat.atime = t;
266	        }
267	        if let Some(t) = mtime {
268	            sync.stat.mtime = t;
269	        };
270	
271	        let stat = sync.stat.clone();
272	        drop(sync);
273	        Ok(LookedUp { inode, stat })
274	    }
