+        let last_modified = OffsetDateTime::UNIX_EPOCH + Duration::days(30);
+        for key in keys {
+            let mut obj = MockObject::constant(0xaa, 30, ETag::for_tests());
+            obj.set_last_modified(last_modified);
+            client.add_object(key, obj);
